def smallest_distance_pair(nums, k):
    distances = []
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            distances.append(abs(nums[i] - nums[j]))    # every pair's distance directly
    distances.sort()
    return distances[k - 1]

