def smallest_distance_pair(nums, k):
    nums = sorted(nums)
    n = len(nums)

    def count_at_most(d):
        count, left = 0, 0
        for right in range(n):
            while nums[right] - nums[left] > d:
                left += 1
            count += right - left                     # every left position up to 'left' is valid
        return count

    lo, hi = 0, nums[-1] - nums[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) < k:
            lo = mid + 1
        else:
            hi = mid
    return lo

