import java.util.*;

public class Main {
    static int countAtMost(int[] nums, int d) {
        int count = 0, left = 0;
        for (int right = 0; right < nums.length; right++) {
            while (nums[right] - nums[left] > d) left++;
            count += right - left;                     // every left position up to 'left' is valid
        }
        return count;
    }

    static int smallestDistancePair(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int lo = 0, hi = nums[n - 1] - nums[0];
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (countAtMost(nums, mid) < k) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

